/** Mirror of the database's account_is_live, with wording for the owner. */
function accountState(account, now = Date.now()) {
	if (!account) return {
		live: true,
		label: "",
		warn: false,
		daysLeft: null
	};
	const days = (iso) => iso ? Math.ceil((Date.parse(iso) - now) / DAY) : null;
	switch (account.status) {
		case "trialing": {
			const left = days(account.trial_ends_at);
			if (left === null) return {
				live: true,
				label: "Free trial",
				warn: false,
				daysLeft: null
			};
			if (left <= 0) return {
				live: false,
				label: "Your free trial has ended",
				warn: true,
				daysLeft: 0
			};
			return {
				live: true,
				label: `Free trial: ${left} day${left === 1 ? "" : "s"} left`,
				warn: left <= 3,
				daysLeft: left
			};
		}
		case "active":
		case "past_due": {
			const left = days(account.paid_until);
			if (left === null) return {
				live: true,
				label: account.status === "past_due" ? "Payment due" : "Active",
				warn: account.status === "past_due",
				daysLeft: null
			};
			if (left + 7 <= 0) return {
				live: false,
				label: "Your plan has ended",
				warn: true,
				daysLeft: 0
			};
			if (left <= 0) return {
				live: true,
				label: `Renew within ${left + 7} day${left + 7 === 1 ? "" : "s"} to keep online orders running`,
				warn: true,
				daysLeft: left
			};
			return {
				live: true,
				label: `Paid until ${new Date(Date.parse(account.paid_until ?? "")).toLocaleDateString("en-IN", {
					day: "numeric",
					month: "short",
					year: "numeric"
				})}`,
				warn: left <= 5 || account.status === "past_due",
				daysLeft: left
			};
		}
		case "suspended": return {
			live: false,
			label: "Account suspended",
			warn: true,
			daysLeft: 0
		};
		default: return {
			live: false,
			label: "Account cancelled",
			warn: true,
			daysLeft: 0
		};
	}
}
